// ---- Input validation & prompt construction ----
const incoming = $input.first().json;
const body = incoming.body || incoming;

const company = (body.company_name || '').toString().trim();
if (!company) {
  throw new Error('company_name is required');
}

const industry = (body.industry || 'Unknown').toString().trim();
const location = (body.location || 'India').toString().trim();
const role = (body.prospect_role || 'Not specified').toString().trim();
const meetingDate = (body.meeting_date || 'Not specified').toString().trim();
const notes = (body.notes || '').toString().trim().slice(0, 1500);
const year = new Date().getFullYear();

const prompt =
  `Generate a pre-meeting sales intelligence brief for the following prospect.\n\n` +
  `PROSPECT COMPANY: ${company}\n` +
  `INDUSTRY: ${industry}\n` +
  `LOCATION: ${location}\n` +
  `MEETING WITH (ROLE): ${role}\n` +
  `MEETING DATE: ${meetingDate}\n` +
  `CURRENT YEAR: ${year}\n` +
  (notes ? `REP'S CRM NOTES: ${notes}\n` : '') +
  `\nSearch first, then write. Use Tavily_Company_Search once for background, then ` +
  `Tavily_Recent_News at least three times on ${company} (tax/GST, customs/exports, ` +
  `recent corporate and regulatory news) and once on the ${industry} sector in India. ` +
  `Attach a source_url ONLY when you have a real matching URL from those results; ` +
  `otherwise leave it empty and mark the signal Industry-pattern. ` +
  `Return the brief strictly in the required JSON format.`;

return [{ json: { prompt, company, industry, location, role, meetingDate } }];

// ---- Robust JSON extraction + source-URL integrity guard ----
const item = $input.first().json;
let raw = item.output ?? item.text ?? '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);

let parsed = null;
try {
  let cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start !== -1 && end > start) {
    const jsonStr = cleaned.slice(start, end + 1);
    try {
      parsed = JSON.parse(jsonStr);
    } catch (e1) {
      parsed = JSON.parse(jsonStr.replace(/,\s*}/g, '}').replace(/,\s*]/g, ']'));
    }
  }
} catch (e) {
  parsed = null;
}

if (!parsed || !Array.isArray(parsed.pain_signals)) {
  return [{ json: {
    success: false,
    error: 'Agent returned an unparseable brief. Retry the request.',
    raw_output: raw.slice(0, 2000),
    generated_at: new Date().toISOString()
  } }];
}

// Drop anything that is not a real http(s) URL. Models sometimes emit
// "N/A", "not available", a bare domain, or a hallucinated path.
const isRealUrl = (u) => typeof u === 'string' && /^https?:\/\/[^\s"']+\.[^\s"']+/i.test(u.trim());

parsed.pain_signals = parsed.pain_signals.map((s) => {
  const url = isRealUrl(s.source_url) ? s.source_url.trim() : '';
  return Object.assign({}, s, {
    source_url: url,
    signal_type: url ? (s.signal_type || 'Company-specific') : 'Industry-pattern'
  });
});

// Confidence can never exceed what the sourced signals actually support.
const sourced = parsed.pain_signals.filter((s) => s.source_url).length;
const cap = sourced >= 2 ? 'High' : sourced === 1 ? 'Medium' : 'Low';
const rank = { Low: 0, Medium: 1, High: 2 };
if (rank[parsed.confidence] === undefined || rank[parsed.confidence] > rank[cap]) {
  parsed.confidence = cap;
}

return [{ json: {
  success: true,
  brief: parsed,
  sourced_signals: sourced,
  generated_at: new Date().toISOString(),
  engine: 'MAVERICK v3 — web-signal detection (Tavily + Claude Haiku 4.5 via n8n)'
} }];
